@test
def test_clust2():
    assert close(MeanShift().fit(cov).modes_, E_ms_modes, atol=1e-06)
    assert close(MeanShift().fit(cov).labels_, E_ms_lab, atol=1e-08)
    assert close(MeanShift("normal").fit(cov).modes_, E_ms2_modes, atol=1e-06)
    assert close(GaussianMixture(2, "riemann", None, None, 1e-5, 100, 1).fit(cov).weights_, E_gm_w, atol=1e-06)
    assert close(GaussianMixture(2, "riemann", None, None, 1e-5, 100, 1).fit(cov).means_, E_gm_means, atol=1e-05)
    assert close(GaussianMixture(2, "riemann", None, None, 1e-5, 100, 1).fit(cov).predict_proba(cov), E_gm_pr, atol=1e-05)
    assert close(GaussianMixture(2, "riemann", None, None, 1e-5, 100, 1).fit(cov).score(cov), E_gm_sc, atol=1e-05)
test_clust2()
